  `QueryFilterNum` bigint(20) NOT NULL AUTO_INCREMENT,
  `GroupName` varchar(255) NOT NULL,
  `FilterText` varchar(255) NOT NULL,
  PRIMARY KEY (`QueryFilterNum`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_general_ci;

